import {element as el,request} from './portal-ui.js';
const target=document.querySelector('#results');
if(document.body.dataset.page==='trace'){
const token=new URLSearchParams(location.search).get('sample')||'';
if(!/^[a-f0-9]{32}$/.test(token))target.append(el('p','Mở đường dẫn QR của hũ mẫu do dự án cung cấp.'));
else request('/api/v1/trace/'+token).then(row=>{target.replaceChildren(el('h2',row.data.title));for(const[label,value]of [['Mã mẫu',row.data.sample_code],['Mã hũ',row.data.jar_code],['Mã lô',row.data.lot_code],['Nguồn nguyên liệu',row.data.origin],['Ngày sản xuất',row.data.production_date||'Chưa cung cấp'],['Quy trình',row.data.process_notes||'Chưa cung cấp']])target.append(el('h3',label),el('p',value));target.append(el('p',row.evidence_status),el('p',row.notice));const link=el('a','Góp ý về mẫu →','button dark');link.href='trai-nghiem.html?sample='+encodeURIComponent(row.data.sample_code);target.append(link);}).catch(()=>target.replaceChildren(el('p','Hồ sơ chưa được công bố, đã được rút hoặc chưa kết nối được máy chủ.')));
}else{
const form=document.querySelector('#clause-search');const search=async()=>{target.textContent='Đang tìm nguồn…';try{const data=await request('/api/v1/research/clauses?q='+encodeURIComponent(form.elements.q.value));target.replaceChildren(el('p',data.notice));for(const row of data.items){const d=row.data,card=el('article','','library-note');card.append(el('h2',d.title),el('p',`${d.standard_code} · ${d.edition} · Điều ${d.clause}`),el('p',d.excerpt),el('p','Giới hạn: '+d.limitation),el('p',d.citation));const source=el('a','Mở nguồn gốc ↗');source.href=d.source_url;source.target='_blank';source.rel='noopener noreferrer';card.append(source);target.append(card);}}catch{target.textContent='Chưa kết nối được kho điều khoản. Vui lòng thử lại.';}};form.onsubmit=e=>{e.preventDefault();search();};search();}
